    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};

void helper(TreeNode* root, int targetSum, vector<int>& current, vector<vector<int>>& ans) {
    if (!root) return;
    current.push_back(root->val);
    if (!root->left && !root->right && targetSum == root->val) {
        ans.push_back(current);
    }
    helper(root->left, targetSum - root->val, current, ans);
    helper(root->right, targetSum - root->val, current, ans);
    current.pop_back();
}

vector<vector<int>> pathSum(TreeNode* root, int targetSum) {
    vector<vector<int>> ans;
    vector<int> current;
    helper(root, targetSum, current, ans);
    return ans;
}
