#include <iostream>
#include <string>
#include <unordered_set>
#include <queue>
#include <vector>

using namespace std;

int ladderLength(string beginWord, string endWord, vector<string>& wordList) {
    unordered_set<string> word_set(wordList.begin(), wordList.end());
    if (word_set.find(endWord) == word_set.end()) {
        return 0;
    }

    queue<string> q;
    q.push(beginWord);
    int steps = 1;

    while (!q.empty()) {
        int size = q.size();
        vector<string> current_level;

        for (int i = 0; i < size; i++) {
            string current_word = q.front();
            q.pop();
            if (current_word == endWord) {
                return steps;
            }

            string word_chars = current_word;
            for (int j = 0; j < word_chars.length(); j++) {
                char original_char = word_chars[j];
                for (int k = 0; k < 26; k++) {
                    word_chars[j] = 'a' + k;
                    string new_word = word_chars;
                    if (word_set.find(new_word) != word_set.end()) {
                        q.push(new_word);
                        current_level.push_back(new_word);
                    }
                }
                word_chars[j] = original_char;
            }
        }

        for (const auto& word : current_level) {
            word_set.erase(word);
        }
        steps++;
    }

    return 0;
}

int main() {
    vector<string> wordList = {"hot", "dot", "dog", "lot", "log", "cog"};
