import java.util.ArrayList;
import java.util.List;

public class CombinationSum3 {
    public static List<List<Integer>> combinationSum3(int k, int n) {
        List<List<Integer>> result = new ArrayList<>();
        helper(k, n, 0, new ArrayList<>(), result);
        return result;
    }

    private static void helper(int k, int n, int current, List<Integer> currentComb, List<List<Integer>> result) {
        if (k == 0 && n == 0) {
            result.add(new ArrayList<>(currentComb));
        } else if (k > 0 && n > 0) {
            for (int i = current + 1; i <= 9; i++) {
                currentComb.add(i);
                helper(k - 1, n - i, i, currentComb, result);
                currentComb.remove(currentComb.size() - 1);
            }
        }
    }

    public static void main(String[] args) {
        int k = 3;
        int n = 7;
        List<List<Integer>> result = combinationSum3(k, n);
        System.out.println(result); // [[1, 2, 4]]
    }
}
