public class Solution {
    public List<Integer> countSmaller(int[] nums) {
        int n = nums.length;
        int[] counts = new int[n];
        Integer[] indices = new Integer[n];
        for (int i = 0; i < n; i++) {
            indices[i] = i;
        }
        mergeSort(indices, 0, n - 1, nums, counts);
        List<Integer> result = new ArrayList<>();
        for (int count : counts) {
            result.add(count);
        }
        return result;
    }

    private void mergeSort(Integer[] indices, int start, int end, int[] nums, int[] counts) {
        if (start >= end) {
            return;
        }
        int mid = (start + end) / 2;
        mergeSort(indices, start, mid, nums, counts);
        mergeSort(indices, mid + 1, end, nums, counts);
        merge(indices, start, mid, end, nums, counts);
    }

    private void merge(Integer[] indices, int start, int mid, int end, int[] nums, int[] counts) {
        List<Integer> left = new ArrayList<>();
        List<Integer> right = new ArrayList<>();
        for (int i = start; i <= mid; i++) {
            left.add(indices[i]);
        }
        for (int i = mid + 1; i <= end; i++) {
            right.add(indices[i]);
        }
        int i = 0, j = 0;
        int count = 0;
        while (i < left.size() && j < right.size()) {
            if (nums[left.get(i)] <= nums[right.get(j)]) {
                counts[left.get(i)] += count;
                indices[start++] = left.get(i++);
            } else {
                count += left.size() - i;
                indices[start++] = right.get(j++);
            }
        }
        while (i < left.size()) {
            counts[left.get(i)] += count;
            indices[start++] = left.get(i++);
        }
        while (j < right.size()) {
            indices[start++] = right.get(j++);
        }
