public class LexicalOrder {
    public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        for (int i = 1; i <= 9; i++) {
            lexicographicalOrderHelper(i, n, result);
        }
        return result;
    }

    private static void lexicographicalOrderHelper(int current, int n, List<Integer> result) {
        if (current > n) {
            return;
        }

        result.add(current);
        for (int i = 0; i <= 9; i++) {
            lexicographicalOrderHelper(current * 10 + i, n, result);
        }
    }

    public static void main(String[] args) {
        int n = 13;
        List<Integer> result = lexicalOrder(n);
        System.out.println(result);
    }
}
