    public int splitArray(int[] nums, int m) {
        long left = 0, right = 0;
        for (int num : nums) {
            left = Math.max(left, (long)num);
            right += num;
        }

        while (left < right) {
            long mid = (left + right) / 2;
            int count = 1;
            long curSum = 0;
            for (int num : nums) {
                curSum += num;
                if (curSum > mid) {
                    curSum = num;
                    count++;
                }
            }

            if (count > m) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        return (int)left;
    }

    public static void main(String[] args) {
        Solution solution = new Solution();
        int[] nums = {7, 2, 5, 10, 8};
        int k = 2;
        System.out.println(solution.splitArray(nums, k));
    }
}
