def word_squares(words: List[str]) -> List[List[str]]:
    prefix_map = build_prefix_map(words)
    squares = []
    for word in words:
        square = [word]
        search_squares(1, len(word), square, prefix_map, squares)
    return squares

def search_squares(index: int, length: int, square: List[str], prefix_map: Dict[str, List[str]], squares: List[List[str]]) -> None:
    if index == length:
        squares.append(square.copy())
        return
    prefix = build_prefix(square, index)
    for word in prefix_map.get(prefix, []):
        square.append(word)
        search_squares(index + 1, length, square, prefix_map, squares)
        square.pop()

def build_prefix(square: List[str], index: int) -> str:
    return ''.join([s[index] for s in square])

def build_prefix_map(words: List[str]) -> Dict[str, List[str]]:
    prefix_map = {}
    for word in words:
        for i in range(len(word) + 1):
            prefix = word[:i]
            if prefix not in prefix_map:
                prefix_map[prefix] = []
            prefix_map[prefix].append(word)
    return prefix_map
