import java.util.PriorityQueue;

public class Solution {
    public int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
        int n = profits.length;
        int[][] projectPool = new int[n][2];

        for (int i = 0; i < n; i++) {
            projectPool[i][0] = capital[i];
            projectPool[i][1] = profits[i];
        }

        // Sort projects by capital requirement in descending order
        java.util.Arrays.sort(projectPool, (a, b) -> Integer.compare(b[0], a[0]));

        PriorityQueue<Integer> profitPool = new PriorityQueue<>();

        while (k > 0) {
            // Add all projects that can be started with the current capital
            while (projectPool.length > 0 && projectPool[projectPool.length - 1][0] <= w) {
                profitPool.add(projectPool[projectPool.length - 1][1]);
                projectPool = java.util.Arrays.copyOfRange(projectPool, 0, projectPool.length - 1);
            }

            if (profitPool.isEmpty()) {
                break;
            }

            w += profitPool.poll();
            k--;
        }

        return w;
    }
}
