                while (newX >= 0 && newX < m && newY >= 0 && newY < n && maze[newX][newY] == 0) {
                    newX += dir[0];
                    newY += dir[1];
                    step++;
                }

                newX -= dir[0];
                newY -= dir[1];

                if (dist[newX][newY] > dist[x][y] + step) {
                    dist[newX][newY] = dist[x][y] + step;
                    q.add(new int[]{newX, newY});
