import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        String[] timePoints = {"23:59", "00:00"};
        System.out.println(findMinDifference(timePoints));
    }

    public static int findMinDifference(String[] timePoints) {
        Arrays.sort(timePoints);
        int minDifference = Integer.MAX_VALUE;

        for (int i = 0; i < timePoints.length; i++) {
            int h1 = Integer.parseInt(timePoints[i].substring(0, 2));
            int m1 = Integer.parseInt(timePoints[i].substring(3, 5));
            int h2 = Integer.parseInt(timePoints[(i + 1) % timePoints.length].substring(0, 2));
            int m2 = Integer.parseInt(timePoints[(i + 1) % timePoints.length].substring(3, 5));
            int curDifference = Math.abs((h1 * 60 + m1) - (h2 * 60 + m2));
            minDifference = Math.min(minDifference, 1440 - curDifference > 720 ? 1440 - curDifference : curDifference);
        }

        return minDifference;
    }
}
