    public static boolean findTripletEqualSum(int[] nums) {
        int n = nums.length;
        int[] prefixSum = new int[n + 1];

        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + nums[i];
        }

        for (int i = 1; i < n - 2; i++) {
            for (int j = i + 2; j < n - 1; j++) {
                for (int k = j + 2; k < n; k++) {
                    int s1 = prefixSum[i];
                    int s2 = prefixSum[j] - prefixSum[i + 1];
                    int s3 = prefixSum[k] - prefixSum[j + 1];
                    int s4 = prefixSum[n] - prefixSum[k + 1];
                    if (s1 == s2 && s2 == s3 && s3 == s4) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    public static void main(String[] args) {
        int[] nums = {1, 2, 1, 2, 1, 2, 1};
        System.out.println(findTripletEqualSum(nums));
