public class Solution {
    public String splitLoopedString(String[] strs) {
        String ans = "";
        String cur = "";
        for (String s : strs) {
            cur += max(s, new StringBuilder(s).reverse().toString());
        }

        for (int i = 0; i < strs.length; i++) {
            String s = strs[i];
            for (String xstr : new String[]{s, new StringBuilder(s).reverse().toString()}) {
                for (int j = 0; j < xstr.length(); j++) {
                    String t = xstr.substring(j) + cur.substring(xstr.length()) + cur.substring(0, xstr.length()) + xstr.substring(0, j);
                    ans = Math.max(ans, t);
                }
            }
            cur = cur.substring(s.length()) + cur.substring(0, s.length());
        }

        return ans;
    }

    private String max(String a, String b) {
        return a.compareTo(b) > 0 ? a : b;
    }
}
