import java.util.*;

public class Solution {
    public static List<String> findRestaurant(String[] list1, String[] list2) {
        Map<String, Integer> restaurantMap = new HashMap<>();
        for (int i = 0; i < list1.length; i++) {
            restaurantMap.put(list1[i], i);
        }

        int minSum = Integer.MAX_VALUE;
        List<String> result = new ArrayList<>();
        for (int j = 0; j < list2.length; j++) {
            if (restaurantMap.containsKey(list2[j])) {
                int totalSum = j + restaurantMap.get(list2[j]);
                if (totalSum < minSum) {
                    result.clear();
                    result.add(list2[j]);
                    minSum = totalSum;
                } else if (totalSum == minSum) {
                    result.add(list2[j]);
                }
            }
        }

        return result;
    }
}
