std::vector<int> findRedundantDirectedConnection(std::vector<std::vector<int>>& edges) {
    int n = edges.size();
    std::vector<int> parent(n + 1, 0);
    int candidateA = -1, candidateB = -1;

    for (const auto& edge : edges) {
        int u = edge[0], v = edge[1];
        if (parent[v] > 0) {
            candidateA = parent[v];
            candidateB = v;
            parent[v] = u;
        } else {
            parent[v] = u;
        }
    }

    for (int i = 1; i <= n; ++i) {
        int cycle = i;
        int steps = n;
        while (parent[cycle] != 0 && steps > 0) {
            cycle = parent[cycle];
            --steps;
        }
        if (steps == 0) {
            if (candidateA == -1) {
                return {parent[i], i};
            } else {
                return {candidateA, candidateB};
            }
        }
    }

    return {candidateB, -1};
}
