        target = totalSum `div` k
        visited = replicate (length nums) False

dfs :: [Int] -> [Bool] -> Int -> Int -> Int -> Int -> Bool
dfs nums visited start target currSum k
    | k == 1 = True
    | currSum == target = dfs nums visited 0 target 0 (k - 1)
    | otherwise = or [dfs nums (setVisited i True visited) (i + 1) target (currSum + nums !! i) k
