import java.util.*;

class Solution {
    public int numDistinctIslands(int[][] grid) {
        Set<String> distinctIslands = new HashSet<>();

        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == 1) {
                    List<Integer> island = new ArrayList<>();
                    dfs(grid, r, c, r, c, island);
                    String normalizedIsland = normalizeIsland(island);
                    distinctIslands.add(normalizedIsland);
                }
            }
        }

        return distinctIslands.size();
    }

    private void dfs(int[][] grid, int r, int c, int r0, int c0, List<Integer> island) {
        if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length || grid[r][c] == 0) {
            return;
        }

        grid[r][c] = 0;
        island.add((r - r0) * 1000 + (c - c0));
        dfs(grid, r + 1, c, r0, c0, island);
        dfs(grid, r - 1, c, r0, c0, island);
        dfs(grid, r, c + 1, r0, c0, island);
        dfs(grid, r, c - 1, r0, c0, island);
    }

    private String normalizeIsland(List<Integer> island) {
        List<Integer> normalizedIsland = new ArrayList<>();
        for (int p : island) {
            int x = p / 1000;
            int y = p % 1000;
            normalizedIsland.add(x);
            normalizedIsland.add(y);
            normalizedIsland.add(x);
            normalizedIsland.add(-y);
            normalizedIsland.add(-x);
