public class BipartiteGraphChecker {
    public static boolean isBipartite(List<List<Integer>> graph) {
        int n = graph.size();
        int[] colors = new int[n];

        for (int i = 0; i < n; i++) {
            if (colors[i] == 0 && !dfs(i, 1, graph, colors)) {
                return false;
            }
        }

        return true;
    }

    private static boolean dfs(int node, int color, List<List<Integer>> graph, int[] colors) {
        if (colors[node] != 0) {
            return colors[node] == color;
        }

        colors[node] = color;
        for (int neighbor : graph.get(node)) {
            if (!dfs(neighbor, 3 - color, graph, colors)) {
                return false;
            }
        }

        return true;
    }

    public static void main(String[] args) {
        List<List<Integer>> graph = new ArrayList<>();
        graph.add(List.of(1, 2, 3));
        graph.add(List.of(0, 2));
        graph.add(List.of(0, 1, 3));
        graph.add(List.of(0, 2));

        System.out.println(isBipartite(graph)); // Output: false
    }
