vector<vector<int>> findItinerary(vector<vector<string>>& tickets) {
    unordered_map<string, vector<string>> graph;
    for (auto& ticket : tickets) {
        graph[ticket[0]].push_back(ticket[1]);
    }
    for (auto& pair : graph) {
        sort(pair.second.begin(), pair.second.end());
    }
    vector<string> path;
    function<bool(string)> dfs = [&](string airport) {
        if (path.size() == tickets.size() + 1) {
            return true;
        }
        for (int i = 0; i < graph[airport].size(); ++i) {
            string nextAirport = graph[airport][i];
            graph[airport].erase(graph[airport].begin() + i);
            path.push_back(nextAirport);
            if (dfs(nextAirport)) {
                return true;
            }
            graph[airport].insert(graph[airport].begin() + i, nextAirport);
            path.pop_back();
        }
        return false;
    };
    dfs("JFK");
    return path;
}
