    public int shortestPathLength(int[][] graph) {
        int n = graph.length;
        Queue<int[]> q = new LinkedList<>();

        for(int i = 0; i < n; i++) {
            q.add(new int[]{i, 1 << i});
        }
        int steps = -1;
        boolean[][] visited = new boolean[n][1 << n];

        while(!q.isEmpty()) {
            steps++;
            int size = q.size();

            for(int k = 0; k < size; k++) {
                int[] curr = q.poll();
                int currNode = curr[0];
