int sumOfWidths(std::vector<int>& nums) {
    const int MOD = 1000000007;
    std::sort(nums.begin(), nums.end());
    int c = 1, res = 0;
    int n = nums.size();

    for (int i = 0; i < n; ++i) {
        res = (res + (nums[i] - nums[n - i - 1]) * c) % MOD;
        c = (c * 2) % MOD;
    }

    return res;
}
