CREATE FUNCTION find_kth_positive(@nums TABLE (num INT), @k INT)
RETURNS INT
AS
BEGIN
  DECLARE @left INT, @right INT, @mid INT
  SET @left = 0
  SET @right = (SELECT COUNT(*) FROM @nums)
  WHILE @left < @right
  BEGIN
    SET @mid = FLOOR((@left + @right) / 2)
    IF (SELECT num - @mid - 1 FROM @nums WHERE @mid = ROW_NUMBER() OVER (ORDER BY num)) < @k
      SET @left = @mid + 1
    ELSE
      SET @right = @mid
  END
  RETURN @left + @k
END
