int maxUncrossedLines(const std::vector<std::vector<int>>& books, int shelfWidth) {
    int m = books.size();
    int n = books[0].size();
    std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n + 1, 0));

    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (books[i - 1][j - 1] == books[i - 1][j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = std::max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }

    return dp[m][n];
}

int main() {
    std::vector<std::vector<int>> books = {{1,1},{2,3},{2,3},{1,1},{1,1},{1,1},{1,2}};
    int shelfWidth = 4;
    int result = maxUncrossedLines(books, shelfWidth);
    std::cout << "Maximum number of uncrossed lines: " << result << std::endl;
    return 0;
}
