    public bool CanPartitionKSubsets(int[] nums, int k) {
        int n = nums.Length;
        int totalSum = nums.Sum();
        if (totalSum % k != 0) {
            return false;
        }
        int target = totalSum / k;
        bool[,] dp = new bool[n + 1, target + 1];
        dp[0, 0] = true;
        for (int i = 1; i <= n; i++) {
