int maxLevelSum(TreeNode* root) {
    if (!root) return 0;

    std::queue<TreeNode*> q;
    q.push(root);
    int level = 0, max_sum = std::numeric_limits<int>::min(), result_level = 0;

    while (!q.empty()) {
        int qlen = q.size();
        int sum = 0;
        level++;

