public class KeyboardTime {
    public static int calculateTime(String keyboard, String word) {
        int time = 0;
        int prevIndex = 0;
        Map<Character, Integer> charToIndex = new HashMap<>();

        for (int i = 0; i < keyboard.length(); i++) {
            charToIndex.put(keyboard.charAt(i), i);
