import java.util.Arrays;
import java.util.Comparator;

public class JobScheduling {
    public static int jobScheduling(int[] startTime, int[] endTime, int[] profit) {
        int n = startTime.length;
        Job[] jobs = new Job[n];
        for (int i = 0; i < n; i++) {
            jobs[i] = new Job(endTime[i], startTime[i], profit[i]);
        }
        Arrays.sort(jobs, Comparator.comparingInt(j -> j.endTime));

        int[] dp = new int[n];
        dp[0] = jobs[0].profit;

        for (int i = 1; i < n; i++) {
            int L = latestNonConflict(jobs, i);
            dp[i] = Math.max(dp[i - 1], (L == -1 ? 0 : dp[L]) + jobs[i].profit);
        }

        return dp[n - 1];
    }

    private static int latestNonConflict(Job[] jobs, int index) {
        int startTimeToFind = jobs[index].startTime;
        int left = 0, right = index - 1;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (jobs[mid].endTime <= startTimeToFind) {
                if (jobs[mid + 1].endTime <= startTimeToFind) {
                    left = mid + 1;
                } else {
                    return mid;
                }
            } else {
                right = mid - 1;
            }
        }
        return -1;
    }

    static class Job {
        int endTime;
        int startTime;
        int profit;

        Job(int endTime, int startTime, int profit) {
            this.endTime = endTime;
            this.startTime = startTime;
            this.profit = profit;
        }
    }
}
