def is_palindrome(arr, i, j):
    while i < j:
        if arr[i] != arr[j]:
            return False
        i += 1
        j -= 1
    return True

def min_removals(arr, i, j, dp):
    if i > j:
        return 0
    if i == j:
        return 1
    if dp[i][j] != -1:
        return dp[i][j]

    ans = min_removals(arr, i + 1, j, dp) + 1
    for k in range(i + 1, j + 1):
        if arr[i] == arr[k]:
            ans = min(ans, min_removals(arr, i + 1, k - 1, dp) + min_removals(arr, k + 1, j, dp))
    dp[i][j] = ans
    return ans

