std::vector<std::vector<int>> matrix_block_sum(std::vector<std::vector<int>>& mat, int k) {
    int m = mat.size(), n = mat[0].size();
    std::vector<std::vector<int>> answer(m, std::vector<int>(n, 0));

    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            for (int r = std::max(0, i - k); r < std::min(m, i + k + 1); ++r) {
                for (int c = std::max(0, j - k); c < std::min(n, j + k + 1); ++c) {
                    answer[i][j] += mat[r][c];
                }
            }
        }
    }

    return answer;
}
