        boolean useLetter = letters.size() > digits.size();

        while (!letters.isEmpty() || !digits.isEmpty()) {
            if (useLetter) {
                result.append(letters.pollLast());
            } else {
                result.append(digits.pollLast());
            }
            useLetter = !useLetter;
        }

        return result.toString();
    }
}
