        int n = grid[0].size();
        int mod = 1000000007;
        std::vector<std::vector<std::vector<long long>>> dp(m, std::vector<std::vector<long long>>(n, std::vector<long long>(2, 0)));
        dp[0][0][0] = grid[0][0];
        dp[0][0][1] = grid[0][0];
        for (int i = 1; i < m; i++) {
