int waysToSplit(std::vector<int>& nums) {
    const int MOD = 1000000007;
    int n = nums.size();
    std::vector<long long> prefixSum(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        prefixSum[i + 1] = prefixSum[i] + nums[i];
    }

