def min_operations(target: List[int], arr: List[int]) -> int:
    pos = {num: idx for idx, num in enumerate(target)}

    dp = []
    for num in arr:
        if num in pos:
            idx = bisect.bisect_left(dp, pos[num])
            if idx == len(dp):
                dp.append(pos[num])
            else:
                dp[idx] = pos[num]

    return len(target) - len(dp)
```


