std::vector<int> maximizeXor(const std::vector<int>& nums, const std::vector<std::pair<int, int>>& queries) {
    std::vector<int> trie[32];
    std::vector<int> ans(queries.size());

    std::sort(nums.begin(), nums.end());
    std::vector<std::pair<int, int>> new_queries;
    for (int i = 0; i < queries.size(); ++i) {
        new_queries.emplace_back(queries[i].second, queries[i].first, i);
    }
    std::sort(new_queries.begin(), new_queries.end());

    int idx = 0;
    for (const auto& [m, x, i] : new_queries) {
        while (idx < nums.size() && nums[idx] <= m) {
            int t = nums[idx];
            idx++;
            int cur = 0;
            for (int j = 31; j >= 0; --j) {
                int bit = (t >> j) & 1;
                cur = trie[j][bit];
