public int kthLargestValue(int[][] matrix, int k) {
    int m = matrix.length;
    int n = matrix[0].length;
    int[][] prefixXOR = new int[m + 1][n + 1];
    PriorityQueue<Integer> pq = new PriorityQueue<>(k);

