    std::vector<int> getOrder(std::vector<std::vector<int>>& tasks) {
        std::vector<int> taskIndices;
        for (int i = 0; i < tasks.size(); i++) {
            taskIndices.push_back(i);
        }

        std::sort(taskIndices.begin(), taskIndices.end(), [&](int a, int b) {
            return tasks[a][0] < tasks[b][0];
        });

        std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::function<bool(const std::pair<int, int>&, const std::pair<int, int>&)>> minHeap([](const auto& a, const auto& b) {
            if (a.second == b.second) return a.first > b.first;
            return a.second > b.second;
        });

        long time = 0;
        int taskIdx = 0;
        std::vector<int> result;

        while (!taskIndices.empty()) {
            while (taskIdx < taskIndices.size() && tasks[taskIndices[taskIdx]][0] <= time) {
                int idx = taskIndices[taskIdx];
                minHeap.push({idx, tasks[idx][1]});
                taskIndices[taskIdx] = -1;
                taskIdx++;
            }

            if (!minHeap.empty()) {
                auto task = minHeap.top();
                minHeap.pop();
                time += task.second;
                result.push_back(task.first);
            } else if (taskIdx < taskIndices.size()) {
