        int[] nums = {10, 6, 5, 8};
        System.out.println(lonelyNumbers(nums));
    }

    public static List<Integer> lonelyNumbers(int[] nums) {
        Map<Integer, Long> count = Arrays.stream(nums).boxed().collect(Collectors.groupingBy(e -> e, Collectors.counting()));
