int maxFruits(const std::vector<std::pair<int, int>>& fruits, int startPos, int k) {
    int n = fruits.size();
    std::vector<int> left(n + 1, 0), right(n + 1, 0);
    int j = 0;

    for (int i = 0; i < n; ++i) {
        while (j < n && fruits[j].first - fruits[i].first <= k) {
            right[i + 1] += fruits[j].second;
            ++j;
        }
        right[i + 1] += right[i];
        if (j < n && fruits[j].first - startPos <= k) {
            right[0] += fruits[j].second;
            ++j;
        }
    }

    j = n - 1;
    for (int i = n - 1; i >= 0; --i) {
        while (j >= 0 && fruits[j].first - fruits[i].first <= k) {
            left[i] += fruits[j].second;
            --j;
        }
        left[i] += left[i + 1];
    }

    int ans = 0;
    for (int i = 0; i < n; ++i) {
        int rest = std::max(0, k - std::abs(fruits[i].first - startPos));
