        std::queue<int> q;
        std::vector<bool> visited(n, false);
        q.push(start);
        visited[start] = true;

        while (!q.empty()) {
            int current = q.front();
            q.pop();

            if (current == end) {
                return current;
            }

            for (int neighbor : tree[current]) {
                if (!visited[neighbor]) {
