#include <vector>

int minHeightJump(const std::vector<int>& nums, const std::vector<int>& costs) {
    int n = nums.size();
    std::vector<int> dp(n, 1e9);

    dp[0] = 0;
    for (int i = 1; i < n; ++i) {
        int j = i - 1;
        while (j >= 0) {
            if ((nums[j] <= nums[i] && (j == 0 || nums[j - 1] < nums[i])) || (nums[j] > nums[i] && (j == 0 || nums[j - 1] >= nums[i]))) {
                dp[i] = std::min(dp[i], dp[j] + costs[i]);
            }
            --j;
        }
    }
    return dp[n - 1];
}
