import java.util.*;

public class Solution {
    public int longestSubsequence(int[] nums, int k) {
        int n = nums.length;
        Map<Integer, Integer> dp = new HashMap<>();
        int ans = 0;

        for (int num : nums) {
            int temp = 0;
            Integer prev = dp.floorKey(num - k - 1);
            if (prev != null) {
                temp = dp.get(prev);
            }
            dp.put(num, Math.max(dp.getOrDefault(num, 0), temp + 1));
            ans = Math.max(ans, dp.get(num));
