std::vector<int> find_good_indices(const std::vector<int>& nums, int k) {
    std::vector<int> good_indices;
    for (int i = k; i < nums.size() - k; ++i) {
        bool left_non_inc = true;
        for (int j = 1; j < k; ++j) {
            if (nums[i - j - 1] < nums[i - j - 2]) {
                left_non_inc = false;
                break;
            }
        }

        bool right_non_dec = true;
        for (int j = 1; j < k; ++j) {
            if (nums[i + j + 1] < nums[i + j + 2]) {
                right_non_dec = false;
                break;
            }
        }

        if (left_non_inc && right_non_dec) {
            good_indices.push_back(i);
        }
    }

    return good_indices;
}
