// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
};

class Solution {
public:
    vector<int> removeSubtrees(TreeNode* root, vector<int>& queries) {
        vector<int> answer(queries.size());

        for (int i = 0; i < queries.size(); ++i) {
            removeSubtree(root, queries[i]);
            answer[i] = findHeight(root);
        }

        return answer;
    }

    void removeSubtree(TreeNode* node, int val) {
        if (node == nullptr) return;

        if (node->left && node->left->val == val)
            node->left = nullptr;
        else
            removeSubtree(node->left, val);

        if (node->right && node->right->val == val)
            node->right = nullptr;
        else
            removeSubtree(node->right, val);
    }

    int findHeight(TreeNode* node) {
        if (node == nullptr) return -1;

        return 1 + max(findHeight(node->left), findHeight(node->right));
    }
};
