int minOperations(std::vector<int>& nums) {
    int n = nums.size();
    int idx0 = -1;

    for (int i = 0; i < n; i++) {
        if (nums[i] == 0) {
            idx0 = i;
            break;
        }
    }

    int cnt1 = 0;
    int cnt2 = 0;

    for (int i = 1; i < n; i++) {
        if (std::abs(nums[i] - nums[i - 1]) != 1) {
            cnt1 += std::abs(nums[i] - nums[i - 1]) - 1;
        }
    }

    for (int i = idx0 + 1; i < n; i++) {
        if (nums[i] < nums[i - 1]) {
            cnt2++;
        }
    }

    return std::min(cnt1, cnt2);
}

int main() {
