int minTotalDistance(std::vector<int>& robot, std::vector<std::vector<int>>& factory) {
    std::sort(robot.begin(), robot.end());
    std::sort(factory.begin(), factory.end());

    int res = 0;
    int idx = 0;
    for (const auto& f : factory) {
        int f_pos = f[0];
        int f_limit = f[1];
        while (f_limit > 0 && idx < robot.size()) {
