import java.util.List;

public class Solution {
    public int countLcmSubarrays(List<Integer> nums, int k) {
        int count = 0;
        for (int i = 0; i < nums.size(); i++) {
            int currLcm = nums.get(i);
            for (int j = i; j < nums.size(); j++) {
                currLcm = lcm(currLcm, nums.get(j));
                if (currLcm == k) {
                    count++;
                }
            }
        }
        return count;
    }

    private int lcm(int a, int b) {
        int temp = a;
        while (temp % b != 0) {
            temp += a;
        }
        return temp;
    }
}
