using namespace std;

int numBeautifulPartitions(const string& s, int k, int minLength) {
    const int MOD = 1e9 + 7;
    unordered_set<char> primes = {'2', '3', '5', '7'};
    int n = s.length();
    vector<vector<int>> dp(n + 1, vector<int>(k + 1, 0));
    dp[0][0] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= k; ++j) {
            for (int l = minLength; l <= i && i - l >= j - 1; ++l) {
                if (primes.count(s[i - l]) && !primes.count(s[i - 1])) {
                    dp[i][j] += dp[i - l][j - 1];
                    if (dp[i][j] >= MOD) dp[i][j] -= MOD;
                }
            }
        }
    }

    return dp[n][k];
}
