#include <iostream>
#include <vector>
#include <queue>
#include <unordered_map>

using namespace std;

int maxGroups(int n, vector<vector<int>>& edges) {
    unordered_map<int, vector<int>> graph;
    vector<int> color(n + 1, 0);

    for (const auto& edge : edges) {
        graph[edge[0]].push_back(edge[1]);
        graph[edge[1]].push_back(edge[0]);
    }

    int max_group = 0;
    for (int i = 1; i <= n; ++i) {
        if (color[i] == 0) {
            queue<int> q;
            q.push(i);
            color[i] = 1;
            while (!q.empty()) {
                int node = q.front();
                q.pop();
                max_group = max(max_group, color[node]);
                for (int neighbor : graph[node]) {
                    if (color[neighbor] == 0) {
                        color[neighbor] = color[node] + 1;
                        q.push(neighbor);
                    } else if (color[neighbor] == color[node]) {
                        return -1;
                    }
                }
            }
        }
    }

    return max_group;
}

int main() {
    int n = 6;
    vector<vector<int>> edges = {{1, 2}, {1, 4}, {1, 5}, {2, 6}, {2, 3}, {4, 6}};
    cout << maxGroups(n, edges) << endl;
    return 0;
}
