std::vector<int> length_of_cycle(int n, std::vector<std::pair<int, int>>& queries) {
    std::vector<int> result;
    for (const auto& query : queries) {
        int A = query.first, B = query.second;
        int depth_A = 0, depth_B = 0;
        while (A != B) {
            if (A < B) {
                std::swap(A, B);
            }
            A >>= 1;
            depth_A++;
        }
        result.push_back(depth_A + depth_B);
    }
    return result;
}
