from typing import List

def top_k_students(positive_feedback: List[str], negative_feedback: List[str], report: List[str], student_id: List[int], k: int) -> List[int]:
    points = {id: 0 for id in student_id}
    for i in range(len(report)):
        pos_count = 0
        neg_count = 0
        for pos in positive_feedback:
            pos_index = report[i].find(pos)
            while pos_index != -1:
                pos_count += 1
                pos_index = report[i].find(pos, pos_index + len(pos))
        for neg in negative_feedback:
            neg_index = report[i].find(neg)
            while neg_index != -1:
                neg_count += 1
                neg_index = report[i].find(neg, neg_index + len(neg))
        points[student_id[i]] += 3 * pos_count - neg_count

    students = sorted(student_id, key=lambda x: (-points[x], x))
    return students[:k]
```


