    public int countSquareFreeSubsets(int[] nums) {
        Map<Integer, Integer> counter = new HashMap<>();
        for (int num : nums) {
            counter.put(num, counter.getOrDefault(num, 0) + 1);
        }
        int MOD = 1000000007;

        int[][] dp = new int[61][1001];
        dp[0][0] = 1;
        int idx = 0;
        for (Map.Entry<Integer, Integer> entry : counter.entrySet()) {
            idx++;
            int num = entry.getKey();
            int freq = entry.getValue();
            for (int sq = 0; sq < 61; sq++) {
                for (int ns = 0; ns < 1001 - freq; ns++) {
                    dp[idx][ns + freq] = (dp[idx][ns + freq] + dp[idx - 1][ns] * ((1 << freq) - 1) % MOD) % MOD;
                    dp[idx][ns] = (dp[idx][ns] + dp[idx - 1][ns]) % MOD;

                    if ((sq / num) % 2 == 1) {
                        dp[idx][ns + freq] = (dp[idx][ns + freq] - dp[idx - 1][ns] * ((1 << (freq - 1)) - 1) % MOD + MOD) % MOD;
                    }
                }
            }
        }
        return dp[idx][0];
